from concurrent.futures import ThreadPoolExecutor, as_completed
from copy import deepcopy
from functools import partial
from os import listdir, path, remove
from shutil import move, rmtree
from threading import Lock
from time import sleep
from typing import Callable

from ta_logcollector.utils.common import copy_from_remote_location
from ta_logcollector.utils.enums import StatusCode
from ta_logcollector.utils.internal import create_dir
from ta_logcollector.utils.proxy_client import (
    send_compress_logs_request,
    send_disable_enb_security_request,
    send_quit,
    send_start_additional_request,
    send_start_request,
    send_stop_additional_request,
    send_stop_request,
)


def start_runners(logger, hosts, log_dir, plugins, additional_collecting=False, timeout=0):
    # type: (Logger, dict, str, dict, bool, int) -> Dict[str, Any]
    """
    Sends req_start to provided hosts to start remote Runner and all plugins
    :param logger: network logger
    :param hosts: dictionary with information about hosts
    :param log_dir: directory where logs should be stored
    :param plugins: plugins to be started with their config
    :param additional_collecting: information whether it's regular or additional start
    :param timeout: timeout in seconds after which lc_server will stop runner by itself if stop is not received
    :return: reply with status and state from the server
    """

    def _start_runner(lock, host):
        host_id, host_data = host
        _plugins = deepcopy(plugins)
        with lock:
            clear_unnecessary_plugin_data(_plugins, host_id)
        start_func = send_start_request if not additional_collecting else send_start_additional_request
        ret = start_func(logger, host_data.addr, msg_adds={"log_dir": log_dir, "plugins": _plugins, "timeout": timeout})
        return {host_data.addr: ret}

    runner_plugin_changer_lock = Lock()
    return perform_runner_function(partial(_start_runner, runner_plugin_changer_lock), hosts)


def stop_runners(logger, hosts, stop_plugins=None, additional_collecting=False):
    # type: (Logger, dict, Optional[list], bool) -> Dict[str, Any]
    """
    Sends req_stop to provided hosts to start remote Runner and all plugins
    :param logger: network logger
    :param hosts: dictionary with information about hosts
    :param stop_plugins: list of plugins to be stopped. If nothing provided, all will be stopped
    :param additional_collecting: information whether it's regular stop or for additional logs
    :return: reply with status and state from the server
    """
    stop_plugins = stop_plugins if stop_plugins else []

    def _stop_runner(host):
        host_id, host_data = host
        stop_func = send_stop_request if not additional_collecting else send_stop_additional_request
        ret = stop_func(logger, host_data.addr, msg_adds={"stop_plugins": stop_plugins})
        return {host_data.addr: ret}

    return perform_runner_function(_stop_runner, hosts)


def quit_lc_servers_sequentially(logger, hosts):
    """
    Sends `quit` to provided hosts to quit lc_servers.
    This is done sequentially as since Python3.9 it's forbidden to start thread in __del__.
    :param logger: network logger
    :param hosts: dictionary with information about VMs (hosts)
    :return: reply with status and state from the server
    """
    for host_id, host_data in hosts.items():
        send_quit(logger, host_data.addr)
    sleep(0.1)  # sleep to let all quit messages to be captured by logger before it terminates


def perform_runner_function(func: Callable, hosts: dict):
    with ThreadPoolExecutor(max_workers=len(hosts)) as executor:
        results = list(executor.map(func, hosts.items()))
    return {
        addr: {"status": ret["status"], "state": ret["state"]} for result in results for addr, ret in result.items()
    }


def clear_unnecessary_plugin_data(plugins, host_id):
    # type: (dict, str) -> None
    """
    Removes part of plugin start request if not necessary. This should not be called on main VM.
    :param plugins: list of plugins to activate with all necessary data
    :param host_id: VirtualMachine ID: ex 'vm1', 'vm2' etc.
    """
    plugins_need_cleaning = ["bip", "syslog", "emil", "tti_trace"]
    plugins_chosen_to_clean = [plugin for plugin in plugins_need_cleaning if plugin in plugins]
    for plugin in plugins_chosen_to_clean:
        clearing_method = globals()[f"clear_unnecessary_{plugin}_data"]
        clearing_method(plugins, host_id)
    if host_id != "vm1":
        if "final_report" in plugins:
            plugins["final_report"]["kwargs"]["bts_info"] = False
        for plugin in ["epc", "alarms", "wireshark"]:
            if plugin in plugins:
                del plugins[plugin]


def clear_unnecessary_tti_trace_data(plugins: dict, host_id: str) -> dict:
    """
    Removes part of tti_trace plugin start request if not necessary.
    """
    plugins["tti_trace"]["kwargs"] = plugins["tti_trace"]["kwargs"][host_id]
    return plugins


def clear_unnecessary_emil_data(plugins, host_id):
    # type: (dict, str) -> dict
    """
    Removes part of emil plugin start request if not necessary.
    :param plugins: list of plugins to activate with all necessary data
    :param host_id: VirtualMachine ID: ex 'vm1', 'vm2' etc.
    :return: list of plugins to activate with cleared unnecessary emil data
    """
    plugins["emil"]["kwargs"] = plugins["emil"]["kwargs"][host_id]
    return plugins


def clear_unnecessary_syslog_data(plugins, host_id):
    # type: (dict, str) -> dict
    """
    Removes part of syslog plugin start request if not necessary.
    :param plugins: list of plugins to activate with all necessary data
    :param host_id: VirtualMachine ID: ex 'vm1', 'vm2' etc.
    :return: list of plugins to activate with cleared unnecessary syslog data
    """
    current_vm = {"compress": plugins["syslog"]["kwargs"].pop("compress")}
    for vm in list(plugins["syslog"]["kwargs"].keys()):
        if vm != host_id:
            del plugins["syslog"]["kwargs"][vm]
        else:
            current_vm.update(plugins["syslog"]["kwargs"][vm])
    plugins["syslog"]["kwargs"] = current_vm
    return plugins


def clear_unnecessary_bip_data(plugins, host_id):
    # type: (dict, str) -> dict
    """
    Removes part of bip plugin start request if not necessary.
    :param plugins: list of plugins to activate with all necessary data
    :param host_id: VirtualMachine ID: ex 'vm1', 'vm2' etc.
    :return: list of plugins to activate with cleared unnecessary bip data
    """
    current_vm = {}
    for vm in list(plugins["bip"]["kwargs"]):
        if vm != host_id:
            del plugins["bip"]["kwargs"][vm]
        else:
            vm_cells = plugins["bip"]["kwargs"][vm]["phy_cell_ids"]
            interface = plugins["bip"]["kwargs"][vm]["interface"]
            current_vm = {"interface": interface, "phy_cell_ids": vm_cells}
    if not current_vm:
        del plugins["bip"]
    else:
        plugins["bip"] = {"kwargs": current_vm}
    return plugins


def _get_logs_done_callback(logger, host_data, log_dir, future):
    # type: (Logger, dict, str, Future) -> None
    """
    Gets result for Runner stop future and creates proper directory tree.
    :param logger: network logger
    :param host_data: dictionary with information about hosts
    :param log_dir: directory where logs should be stored
    :param future: Future object upon which callback should be called
    """
    result = future.result()
    if "logs_location" not in result:
        logger.warning("Archive location not provided by remote host, cannot copy logs!")
        return
    addr, user, passwd, _ = host_data
    create_local_dirs_and_copy_remote_logs(logger, addr, log_dir, passwd, result["logs_location"], user)


def clean_master_vm_logs(host_name, host_addr, single_host, log_dir, provided_logs_path):
    # type: (str, str, bool, str, str) -> None
    """
    Cleans directory with logs on master VM.
    If it's not vm1, then returning.
    In case of `single_host`, leave only target logs directory and put compressed file inside if exists
    Otherwise remove temporary directories and leaves only target logs directory with directories per each VM
    and compressed (or not) logs inside.
    :param host_name: VM name, e.g. "vm1", "vm2"
    :param host_addr: IP address of VM
    :param single_host: whether it's single VM or there are more
    :param log_dir: directory where logs should be stored
    :param provided_logs_path: path to logs stored by appropriate server
    """
    if not host_name == "vm1":
        return
    if path.isdir(provided_logs_path):
        rmtree(provided_logs_path)
    else:
        remove(provided_logs_path)
        log_dir = log_dir if not log_dir.endswith("/") else log_dir[:-1]
        rmtree(f"{log_dir}_{host_addr}")
    if single_host:
        for log_file in listdir(path.join(log_dir, "vm1")):
            move(path.join(log_dir, "vm1", log_file), log_dir)
        rmtree(path.join(log_dir, "vm1"))


def create_local_dirs_and_copy_remote_logs(logger, addr, log_dir, passwd, remote_logs_location, user):
    # type: (Logger, str, str, str, str, str) -> None
    """
    Create local directory for logs and copy from remote host
    :param logger: network logger
    :param addr: IP addr of remote location
    :param log_dir: path to target logs directory
    :param passwd: password for remote host
    :param remote_logs_location: location of remote logs
    :param user: user for remote host
    """
    create_dir(log_dir)
    logger.debug(f"target_path = {log_dir} result_archive = {remote_logs_location}")
    copy_from_remote_location(logger, addr, user, passwd, local_path=log_dir, remote_path=remote_logs_location)


def set_verdict_based_on_host_response(logger, action, host_addr, future):
    # type: (Logger, str, str, Future) -> None
    """
    Gets result for runner start future and logs it
    :param logger: network logger
    :param action: name of performed action
    :param host_addr: IP address of host on which future was called
    :param future: Future object upon which callback should be called
    """
    result = future.result()
    if result["status"] == StatusCode.ServerError:
        logger.debug(f"Server did not respond to {action}")
    elif result["status"] != StatusCode.OK:
        logger.error(
            "Logcollector did NOT {0} - {0} was probably already invoked. Please cleanup LC usage.".format(action)
        )
    elif result["status"] == StatusCode.OK:
        logger.info(f"Logcollector {action.upper()} action finished with success on [{host_addr}]")
    else:
        logger.error("Unknown status code, something went wrong. Please report issue to Logcollector maintainer.")
        logger.debug(f"Unknown status code. Response = {result!r}")


def get_logs_from_runners(logger, hosts, compression_type, remote_logs_path, local_path):
    # type: (Logger, dict, str, str, str) -> None
    """
    Get logs from remote runners and put under log_dir_path
    :param logger: network logger
    :param hosts: dictionary with information about hosts
    :param compression_type: self._log_dir_pathname of compression type which should be used
    :param remote_logs_path: directory which should be compressed on remote
    :param local_path: directory where logs should be stored
    """
    req_compress = {"logs_dir_to_compress": remote_logs_path, "compression_type": compression_type}
    with ThreadPoolExecutor(max_workers=len(hosts)) as executor:
        for host_name, host_data in hosts.items():
            future = executor.submit(send_compress_logs_request, logger, host_data.addr, msg_adds=req_compress)
            future.add_done_callback(partial(_get_logs_done_callback, logger, host_data, local_path))
            future.add_done_callback(partial(set_verdict_based_on_host_response, logger, "compress", host_data.addr))
            logger.info(f"Get logs called for host {host_data}")
    abs_path_to_remove = path.abspath(path.join(remote_logs_path, ".."))
    logger.debug(f"Temporary directory to remove: {abs_path_to_remove}")
    if "logcollector" in abs_path_to_remove:
        rmtree(path.abspath(path.join(remote_logs_path, "..")))  # clear local logs


def disable_enb_security_at_runners(logger, hosts):
    # type: (Logger, dict) -> None
    """
    Disable enb security via runners.
    :param logger: network logger
    :param hosts: dictionary with information about hosts
    """
    futures = []
    with ThreadPoolExecutor(max_workers=len(hosts)) as executor:
        for host_name, host_data in hosts.items():
            future = executor.submit(send_disable_enb_security_request, logger, host_data.addr)
            futures.append(future)
            logger.info(f"Disable enb security called for host {host_data}")
        for future in as_completed(futures):
            future.result()
